('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Spaghetti Bolognese', 'A rich, slow-simmered meat sauce over spaghetti. (Italian)', 4, 60, '[{"quantity":1,"unit":"lb","name":"ground beef"},{"quantity":1,"unit":"","name":"onion"},{"quantity":2,"unit":"clove","name":"garlic"},{"quantity":1,"unit":"","name":"carrot"},{"quantity":1,"unit":"","name":"celery stalk"},{"quantity":1,"unit":"can","name":"crushed tomatoes"},{"quantity":2,"unit":"tbsp","name":"tomato paste"},{"quantity":1,"unit":"tsp","name":"dried oregano"},{"quantity":2,"unit":"tbsp","name":"olive oil"},{"quantity":1,"unit":"lb","name":"spaghetti"},{"name":"salt","quantity":0,"unit":""},{"name":"black pepper","quantity":0,"unit":""}]'::jsonb, ARRAY['Finely chop the onion, carrot, celery and garlic.', 'Heat the oil and soften the vegetables for 8 minutes.', 'Add the beef and brown it, breaking it up.', 'Stir in tomato paste, crushed tomatoes and oregano, then simmer 30 minutes.', 'Cook the spaghetti, drain and serve topped with the sauce.']::text[], ARRAY['dairy-free']::text[], 'https://www.themealdb.com/images/media/meals/sutysw1468247559.jpg'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Margherita Pizza', 'Simple pizza with tomato, mozzarella and basil. (Italian)', 4, 40, '[{"quantity":1,"unit":"lb","name":"pizza dough"},{"quantity":1,"unit":"cup","name":"tomato sauce"},{"quantity":8,"unit":"oz","name":"mozzarella"},{"quantity":1,"unit":"handful","name":"fresh basil"},{"quantity":2,"unit":"tbsp","name":"olive oil"},{"name":"salt","quantity":0,"unit":""}]'::jsonb, ARRAY['Heat the oven to 475F.', 'Stretch the dough onto an oiled tray.', 'Spread tomato sauce and tear the mozzarella over it.', 'Bake 12 to 15 minutes until golden.', 'Top with basil and a drizzle of olive oil.']::text[], ARRAY['vegetarian']::text[], 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/91/Pizza-3007395.jpg/960px-Pizza-3007395.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Fettuccine Alfredo', 'Creamy parmesan pasta ready in minutes. (Italian)', 4, 25, '[{"quantity":1,"unit":"lb","name":"fettuccine"},{"quantity":4,"unit":"tbsp","name":"butter"},{"quantity":1,"unit":"cup","name":"heavy cream"},{"quantity":1,"unit":"cup","name":"parmesan cheese"},{"quantity":2,"unit":"clove","name":"garlic"},{"name":"black pepper","quantity":0,"unit":""},{"name":"salt","quantity":0,"unit":""}]'::jsonb, ARRAY['Cook the fettuccine and save a cup of pasta water.', 'Melt butter with garlic over low heat.', 'Add cream and simmer 3 minutes.', 'Stir in parmesan until smooth.', 'Toss with the pasta, loosening with pasta water if needed.']::text[], ARRAY['vegetarian']::text[], 'https://www.themealdb.com/images/media/meals/0jv5gx1661040802.jpg'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Minestrone Soup', 'Hearty vegetable and bean soup. (Italian)', 6, 50, '[{"quantity":2,"unit":"tbsp","name":"olive oil"},{"quantity":1,"unit":"","name":"onion"},{"quantity":2,"unit":"","name":"carrots"},{"quantity":2,"unit":"","name":"celery stalks"},{"quantity":2,"unit":"clove","name":"garlic"},{"quantity":1,"unit":"","name":"zucchini"},{"quantity":1,"unit":"can","name":"diced tomatoes"},{"quantity":1,"unit":"can","name":"cannellini beans"},{"quantity":6,"unit":"cup","name":"vegetable broth"},{"quantity":1,"unit":"cup","name":"small pasta"},{"quantity":1,"unit":"tsp","name":"dried basil"},{"name":"salt","quantity":0,"unit":""},{"name":"black pepper","quantity":0,"unit":""}]'::jsonb, ARRAY['Chop all the vegetables.', 'Soften onion, carrot, celery and garlic in oil.', 'Add zucchini, tomatoes, broth and basil and simmer 20 minutes.', 'Add beans and pasta and cook until the pasta is tender.', 'Season and serve.']::text[], ARRAY['vegetarian', 'vegan', 'dairy-free']::text[], 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fe/Minestrone_soup_%285%29.jpg/960px-Minestrone_soup_%285%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Chicken Parmesan', 'Crispy breaded chicken under tomato sauce and melted cheese. (Italian)', 4, 45, '[{"quantity":2,"unit":"","name":"chicken breasts"},{"quantity":1,"unit":"cup","name":"breadcrumbs"},{"quantity":0.5,"unit":"cup","name":"parmesan cheese"},{"quantity":2,"unit":"","name":"eggs"},{"quantity":0.5,"unit":"cup","name":"flour"},{"quantity":1,"unit":"cup","name":"tomato sauce"},{"quantity":1,"unit":"cup","name":"mozzarella"},{"quantity":3,"unit":"tbsp","name":"olive oil"},{"name":"salt","quantity":0,"unit":""}]'::jsonb, ARRAY['Slice each breast in half and pound thin.', 'Dredge in flour, then egg, then breadcrumbs mixed with parmesan.', 'Fry in oil until golden on both sides.', 'Top with tomato sauce and mozzarella.', 'Bake at 400F for 15 minutes.']::text[], ARRAY[]::text[], 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/17/Chicken_parm_at_a_diner.jpg/960px-Chicken_parm_at_a_diner.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Mushroom Risotto', 'Creamy arborio rice with mushrooms. (Italian)', 4, 40, '[{"quantity":1.5,"unit":"cup","name":"arborio rice"},{"quantity":8,"unit":"oz","name":"mushrooms"},{"quantity":1,"unit":"","name":"onion"},{"quantity":2,"unit":"clove","name":"garlic"},{"quantity":5,"unit":"cup","name":"vegetable broth"},{"quantity":0.5,"unit":"cup","name":"parmesan cheese"},{"quantity":2,"unit":"tbsp","name":"butter"},{"quantity":2,"unit":"tbsp","name":"olive oil"},{"name":"salt","quantity":0,"unit":""}]'::jsonb, ARRAY['Keep the broth warm in a pot.', 'Cook onion, garlic and mushrooms in oil.', 'Add rice and stir for 2 minutes.', 'Add broth a ladle at a time, stirring, until creamy, about 20 minutes.', 'Stir in butter and parmesan.']::text[], ARRAY['vegetarian', 'gluten-free']::text[], 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a5/Risotto_with_speck_and_goat_cheese_%286101067436%29.jpg/960px-Risotto_with_speck_and_goat_cheese_%286101067436%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Lasagna', 'Layers of pasta, meat sauce and cheese. (Italian)', 8, 90, '[{"quantity":12,"unit":"","name":"lasagna noodles"},{"quantity":1,"unit":"lb","name":"ground beef"},{"quantity":1,"unit":"","name":"onion"},{"quantity":2,"unit":"clove","name":"garlic"},{"quantity":3,"unit":"cup","name":"tomato sauce"},{"quantity":2,"unit":"cup","name":"ricotta cheese"},{"quantity":2,"unit":"cup","name":"mozzarella"},{"quantity":0.5,"unit":"cup","name":"parmesan cheese"},{"quantity":1,"unit":"","name":"egg"},{"quantity":1,"unit":"tsp","name":"dried oregano"}]'::jsonb, ARRAY['Brown beef with onion and garlic, then add tomato sauce and oregano.', 'Mix ricotta with egg and half the parmesan.', 'Cook the noodles.', 'Layer sauce, noodles, ricotta and mozzarella three times.', 'Top with parmesan and bake at 375F for 45 minutes.']::text[], ARRAY[]::text[], 'https://www.themealdb.com/images/media/meals/rvxxuy1468312893.jpg'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Pesto Pasta', 'Fresh basil pesto tossed with pasta. (Italian)', 4, 20, '[{"quantity":1,"unit":"lb","name":"pasta"},{"quantity":2,"unit":"cup","name":"fresh basil"},{"quantity":0.5,"unit":"cup","name":"parmesan cheese"},{"quantity":0.3333333333333333,"unit":"cup","name":"pine nuts"},{"quantity":2,"unit":"clove","name":"garlic"},{"quantity":0.5,"unit":"cup","name":"olive oil"},{"name":"salt","quantity":0,"unit":""}]'::jsonb, ARRAY['Cook the pasta.', 'Blend basil, parmesan, pine nuts, garlic and salt.', 'Stream in olive oil until smooth.', 'Toss the pesto with the drained pasta.']::text[], ARRAY['vegetarian']::text[], 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Espaguetis_carbonara.jpg/960px-Espaguetis_carbonara.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Chicken Tacos', 'Spiced chicken in warm tortillas with fresh toppings. (Mexican)', 4, 30, '[{"quantity":1,"unit":"lb","name":"chicken thighs"},{"quantity":8,"unit":"","name":"corn tortillas"},{"quantity":1,"unit":"tbsp","name":"chili powder"},{"quantity":1,"unit":"tsp","name":"cumin"},{"quantity":1,"unit":"","name":"lime"},{"quantity":1,"unit":"","name":"onion"},{"quantity":1,"unit":"handful","name":"cilantro"},{"quantity":1,"unit":"","name":"avocado"},{"quantity":1,"unit":"cup","name":"salsa"},{"quantity":1,"unit":"tbsp","name":"vegetable oil"},{"name":"salt","quantity":0,"unit":""}]'::jsonb, ARRAY['Toss chicken with chili powder, cumin, salt and oil.', 'Cook in a hot pan 6 minutes per side, then slice.', 'Warm the tortillas.', 'Fill with chicken, diced onion, cilantro, avocado and salsa.', 'Squeeze lime over the top.']::text[], ARRAY['dairy-free']::text[], 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a7/French_Tacos_from_O%27Tacos.jpg/960px-French_Tacos_from_O%27Tacos.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Beef Burritos', 'Seasoned beef, rice and beans wrapped in flour tortillas. (Mexican)', 4, 35, '[{"quantity":1,"unit":"lb","name":"ground beef"},{"quantity":4,"unit":"","name":"flour tortillas"},{"quantity":1,"unit":"cup","name":"cooked rice"},{"quantity":1,"unit":"can","name":"black beans"},{"quantity":1,"unit":"cup","name":"cheddar cheese"},{"quantity":1,"unit":"tbsp","name":"taco seasoning"},{"quantity":0.5,"unit":"cup","name":"salsa"},{"quantity":0.5,"unit":"cup","name":"sour cream"}]'::jsonb, ARRAY['Brown the beef with taco seasoning and a splash of water.', 'Warm the beans.', 'Fill each tortilla with rice, beans, beef, cheese and salsa.', 'Roll up tightly and toast seam-side down in a pan.', 'Serve with sour cream.']::text[], ARRAY[]::text[], 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/Burrito.JPG/960px-Burrito.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Guacamole', 'Fresh avocado dip. (Mexican)', 4, 10, '[{"quantity":3,"unit":"","name":"avocados"},{"quantity":1,"unit":"","name":"lime"},{"quantity":0.5,"unit":"","name":"red onion"},{"quantity":1,"unit":"","name":"tomato"},{"quantity":1,"unit":"handful","name":"cilantro"},{"quantity":1,"unit":"","name":"jalapeno"},{"name":"salt","quantity":0,"unit":""}]'::jsonb, ARRAY['Mash the avocados.', 'Finely chop onion, tomato, cilantro and jalapeno.', 'Mix everything with lime juice and salt.']::text[], ARRAY['vegan', 'vegetarian', 'gluten-free', 'dairy-free']::text[], 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/Guacamole_IMGP1271.jpg/960px-Guacamole_IMGP1271.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Chicken Quesadillas', 'Cheesy grilled tortillas with chicken. (Mexican)', 4, 20, '[{"quantity":2,"unit":"cup","name":"cooked chicken"},{"quantity":4,"unit":"","name":"flour tortillas"},{"quantity":2,"unit":"cup","name":"cheddar cheese"},{"quantity":1,"unit":"","name":"bell pepper"},{"quantity":0.5,"unit":"","name":"onion"},{"quantity":1,"unit":"tsp","name":"cumin"},{"quantity":1,"unit":"tbsp","name":"butter"}]'::jsonb, ARRAY['Slice pepper and onion and cook until soft.', 'Add chicken and cumin.', 'Fill half of each tortilla with cheese and the chicken mix, then fold.', 'Cook in butter until crisp on both sides and the cheese melts.']::text[], ARRAY[]::text[], 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Empanada_flor_de_Calabaza.jpg/960px-Empanada_flor_de_Calabaza.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Black Bean Soup', 'Smoky, filling bean soup. (Mexican)', 6, 40, '[{"quantity":3,"unit":"can","name":"black beans"},{"quantity":1,"unit":"","name":"onion"},{"quantity":3,"unit":"clove","name":"garlic"},{"quantity":1,"unit":"","name":"bell pepper"},{"quantity":1,"unit":"tsp","name":"cumin"},{"quantity":1,"unit":"tsp","name":"smoked paprika"},{"quantity":4,"unit":"cup","name":"vegetable broth"},{"quantity":1,"unit":"","name":"lime"},{"quantity":2,"unit":"tbsp","name":"olive oil"},{"name":"salt","quantity":0,"unit":""}]'::jsonb, ARRAY['Soften onion, pepper and garlic in oil.', 'Add spices, beans and broth.', 'Simmer 20 minutes.', 'Blend half the soup and stir it back in.', 'Finish with lime juice and salt.']::text[], ARRAY['vegan', 'vegetarian', 'gluten-free', 'dairy-free']::text[], 'https://www.themealdb.com/images/media/meals/x0mreq1784577446.jpg'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Chicken Enchiladas', 'Tortillas rolled around chicken and baked in sauce. (Mexican)', 6, 50, '[{"quantity":3,"unit":"cup","name":"cooked chicken"},{"quantity":10,"unit":"","name":"corn tortillas"},{"quantity":2,"unit":"cup","name":"enchilada sauce"},{"quantity":2,"unit":"cup","name":"cheddar cheese"},{"quantity":1,"unit":"","name":"onion"},{"quantity":1,"unit":"tsp","name":"cumin"}]'::jsonb, ARRAY['Mix chicken with cooked onion, cumin and half the cheese.', 'Roll the mixture in tortillas.', 'Lay in a dish and cover with sauce and remaining cheese.', 'Bake at 375F for 25 minutes.']::text[], ARRAY[]::text[], 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Enchilada_Rice_Beans.jpg/960px-Enchilada_Rice_Beans.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Mexican Rice', 'Tomato-red rice side dish. (Mexican)', 6, 35, '[{"quantity":1.5,"unit":"cup","name":"long grain rice"},{"quantity":2,"unit":"tbsp","name":"vegetable oil"},{"quantity":0.5,"unit":"","name":"onion"},{"quantity":2,"unit":"clove","name":"garlic"},{"quantity":1,"unit":"cup","name":"tomato sauce"},{"quantity":2,"unit":"cup","name":"vegetable broth"},{"quantity":1,"unit":"tsp","name":"cumin"},{"name":"salt","quantity":0,"unit":""}]'::jsonb, ARRAY['Fry the rice in oil until lightly golden.', 'Add onion and garlic for 2 minutes.', 'Stir in tomato sauce, broth, cumin and salt.', 'Cover and simmer 20 minutes.']::text[], ARRAY['vegan', 'vegetarian', 'gluten-free', 'dairy-free']::text[], 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Mexican_rice_144235.jpg/960px-Mexican_rice_144235.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Vegetable Fajitas', 'Sizzling peppers and onions in tortillas. (Mexican)', 4, 25, '[{"quantity":3,"unit":"","name":"bell peppers"},{"quantity":1,"unit":"","name":"onion"},{"quantity":8,"unit":"oz","name":"mushrooms"},{"quantity":1,"unit":"tbsp","name":"chili powder"},{"quantity":1,"unit":"tsp","name":"cumin"},{"quantity":2,"unit":"tbsp","name":"vegetable oil"},{"quantity":8,"unit":"","name":"flour tortillas"},{"quantity":1,"unit":"","name":"lime"},{"name":"salt","quantity":0,"unit":""}]'::jsonb, ARRAY['Slice peppers, onion and mushrooms.', 'Cook in oil over high heat until charred.', 'Add spices, salt and lime juice.', 'Serve in warm tortillas.']::text[], ARRAY['vegan', 'vegetarian', 'dairy-free']::text[], 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/Chicken_fajita_platter%2C_Lone_Star_Texas_Grill%2C_Windsor%2C_Ontario%2C_2025-06-14_03.jpg/960px-Chicken_fajita_platter%2C_Lone_Star_Texas_Grill%2C_Windsor%2C_Ontario%2C_2025-06-14_03.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Vegetable Fried Rice', 'Quick fried rice with egg and vegetables. (Chinese)', 4, 20, '[{"quantity":3,"unit":"cup","name":"cooked rice"},{"quantity":2,"unit":"","name":"eggs"},{"quantity":1,"unit":"cup","name":"frozen peas"},{"quantity":1,"unit":"","name":"carrot"},{"quantity":3,"unit":"","name":"green onions"},{"quantity":3,"unit":"tbsp","name":"soy sauce"},{"quantity":1,"unit":"tbsp","name":"sesame oil"},{"quantity":2,"unit":"tbsp","name":"vegetable oil"}]'::jsonb, ARRAY['Dice the carrot and slice the green onions.', 'Scramble the eggs in oil and set aside.', 'Stir-fry carrot and peas 3 minutes.', 'Add rice, soy sauce and sesame oil and fry until hot.', 'Fold in eggs and green onions.']::text[], ARRAY['vegetarian', 'dairy-free']::text[], 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c3/Koh_Mak%2C_Thailand%2C_Fried_rice_with_seafood%2C_Thai_fried_rice.jpg/960px-Koh_Mak%2C_Thailand%2C_Fried_rice_with_seafood%2C_Thai_fried_rice.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Kung Pao Chicken', 'Spicy stir-fried chicken with peanuts. (Chinese)', 4, 30, '[{"quantity":1,"unit":"lb","name":"chicken breast"},{"quantity":0.5,"unit":"cup","name":"peanuts"},{"quantity":6,"unit":"","name":"dried chilies"},{"quantity":3,"unit":"clove","name":"garlic"},{"quantity":1,"unit":"tbsp","name":"ginger"},{"quantity":3,"unit":"","name":"green onions"},{"quantity":3,"unit":"tbsp","name":"soy sauce"},{"quantity":1,"unit":"tbsp","name":"rice vinegar"},{"quantity":1,"unit":"tbsp","name":"sugar"},{"quantity":1,"unit":"tbsp","name":"cornstarch"},{"quantity":2,"unit":"tbsp","name":"vegetable oil"}]'::jsonb, ARRAY['Dice the chicken and toss with cornstarch and 1 tbsp soy sauce.', 'Mix remaining soy sauce, vinegar and sugar.', 'Stir-fry chilies, then the chicken until cooked.', 'Add garlic, ginger and green onions.', 'Pour in the sauce and peanuts and toss.']::text[], ARRAY['dairy-free']::text[], 'https://www.themealdb.com/images/media/meals/1525872624.jpg'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Sweet and Sour Pork', 'Crispy pork with pineapple and peppers. (Chinese)', 4, 40, '[{"quantity":1,"unit":"lb","name":"pork loin"},{"quantity":0.5,"unit":"cup","name":"cornstarch"},{"quantity":1,"unit":"","name":"egg"},{"quantity":1,"unit":"","name":"bell pepper"},{"quantity":1,"unit":"cup","name":"pineapple chunks"},{"quantity":0.5,"unit":"","name":"onion"},{"quantity":0.3333333333333333,"unit":"cup","name":"ketchup"},{"quantity":0.25,"unit":"cup","name":"rice vinegar"},{"quantity":3,"unit":"tbsp","name":"sugar"},{"quantity":1,"unit":"tbsp","name":"soy sauce"},{"quantity":1,"unit":"cup","name":"vegetable oil"}]'::jsonb, ARRAY['Cube the pork, dip in egg, then coat in cornstarch.', 'Fry in oil until crisp and drain.', 'Stir-fry pepper, onion and pineapple.', 'Add ketchup, vinegar, sugar and soy sauce and bubble until glossy.', 'Toss in the pork.']::text[], ARRAY['dairy-free']::text[], 'https://www.themealdb.com/images/media/meals/1529442316.jpg'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Beef and Broccoli', 'Tender beef and broccoli in savory sauce. (Chinese)', 4, 25, '[{"quantity":1,"unit":"lb","name":"flank steak"},{"quantity":4,"unit":"cup","name":"broccoli"},{"quantity":3,"unit":"clove","name":"garlic"},{"quantity":1,"unit":"tbsp","name":"ginger"},{"quantity":0.25,"unit":"cup","name":"soy sauce"},{"quantity":2,"unit":"tbsp","name":"oyster sauce"},{"quantity":1,"unit":"tbsp","name":"brown sugar"},{"quantity":1,"unit":"tbsp","name":"cornstarch"},{"quantity":2,"unit":"tbsp","name":"vegetable oil"}]'::jsonb, ARRAY['Slice the beef thinly and toss with cornstarch.', 'Steam the broccoli 3 minutes.', 'Sear the beef in hot oil.', 'Add garlic, ginger, soy sauce, oyster sauce and sugar.', 'Toss in broccoli and serve.']::text[], ARRAY['dairy-free']::text[], 'https://www.themealdb.com/images/media/meals/m0p0j81765568742.jpg'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Hot and Sour Soup', 'Tangy, peppery soup with tofu and mushrooms. (Chinese)', 4, 25, '[{"quantity":4,"unit":"cup","name":"chicken broth"},{"quantity":8,"unit":"oz","name":"tofu"},{"quantity":4,"unit":"oz","name":"mushrooms"},{"quantity":1,"unit":"","name":"egg"},{"quantity":3,"unit":"tbsp","name":"rice vinegar"},{"quantity":2,"unit":"tbsp","name":"soy sauce"},{"quantity":1,"unit":"tsp","name":"white pepper"},{"quantity":2,"unit":"tbsp","name":"cornstarch"},{"quantity":2,"unit":"","name":"green onions"}]'::jsonb, ARRAY['Bring broth to a simmer with sliced mushrooms.', 'Add cubed tofu, vinegar, soy sauce and pepper.', 'Thicken with cornstarch mixed in water.', 'Drizzle in beaten egg while stirring.', 'Top with green onions.']::text[], ARRAY['dairy-free']::text[], 'https://www.themealdb.com/images/media/meals/1529445893.jpg'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Chow Mein', 'Stir-fried noodles with vegetables. (Chinese)', 4, 25, '[{"quantity":8,"unit":"oz","name":"egg noodles"},{"quantity":2,"unit":"cup","name":"cabbage"},{"quantity":1,"unit":"","name":"carrot"},{"quantity":1,"unit":"cup","name":"bean sprouts"},{"quantity":3,"unit":"","name":"green onions"},{"quantity":3,"unit":"tbsp","name":"soy sauce"},{"quantity":1,"unit":"tbsp","name":"oyster sauce"},{"quantity":1,"unit":"tsp","name":"sesame oil"},{"quantity":2,"unit":"tbsp","name":"vegetable oil"}]'::jsonb, ARRAY['Cook and drain the noodles.', 'Stir-fry cabbage and carrot 3 minutes.', 'Add noodles, soy sauce, oyster sauce and sesame oil.', 'Toss in bean sprouts and green onions.']::text[], ARRAY['dairy-free']::text[], 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a6/Homemade_Chow_mein_with_shrimps_and_meat_with_a_choy_and_Choung.jpg/960px-Homemade_Chow_mein_with_shrimps_and_meat_with_a_choy_and_Choung.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail'),
