('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Beef Bulgogi', 'Sweet-savoury marinated beef. (Korean)', 4, 30, '[{"quantity":1,"unit":"lb","name":"ribeye"},{"quantity":0.25,"unit":"cup","name":"soy sauce"},{"quantity":2,"unit":"tbsp","name":"brown sugar"},{"quantity":1,"unit":"tbsp","name":"sesame oil"},{"quantity":3,"unit":"clove","name":"garlic"},{"quantity":1,"unit":"","name":"pear"},{"quantity":0.5,"unit":"","name":"onion"},{"quantity":2,"unit":"","name":"green onions"},{"quantity":1,"unit":"tsp","name":"sesame seeds"}]'::jsonb, ARRAY['Slice beef very thinly.', 'Grate the pear and garlic and mix with soy sauce, sugar and sesame oil.', 'Marinate the beef 20 minutes.', 'Cook in a hot pan with the onion.', 'Top with green onions and sesame seeds.']::text[], ARRAY['dairy-free']::text[], 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ce/Bulgogi_2.jpg/960px-Bulgogi_2.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail'),
