('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Pho', 'Aromatic beef noodle soup. (Vietnamese)', 4, 60, '[{"quantity":8,"unit":"cup","name":"beef broth"},{"quantity":1,"unit":"","name":"onion"},{"quantity":3,"unit":"slice","name":"ginger"},{"quantity":2,"unit":"","name":"star anise"},{"quantity":1,"unit":"","name":"cinnamon stick"},{"quantity":2,"unit":"tbsp","name":"fish sauce"},{"quantity":8,"unit":"oz","name":"rice noodles"},{"quantity":8,"unit":"oz","name":"sirloin"},{"quantity":1,"unit":"cup","name":"bean sprouts"},{"quantity":1,"unit":"handful","name":"basil"},{"quantity":1,"unit":"","name":"lime"}]'::jsonb, ARRAY['Char onion and ginger in a dry pan.', 'Simmer broth with onion, ginger, star anise and cinnamon 40 minutes.', 'Season with fish sauce and strain.', 'Cook noodles and slice the beef paper-thin.', 'Pour boiling broth over noodles and raw beef and serve with sprouts, basil and lime.']::text[], ARRAY['dairy-free', 'gluten-free']::text[], 'https://www.themealdb.com/images/media/meals/pbzcrx1763765096.jpg'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Fresh Spring Rolls', 'Rice paper rolls with shrimp and herbs. (Vietnamese)', 4, 30, '[{"quantity":12,"unit":"","name":"rice paper wrappers"},{"quantity":8,"unit":"oz","name":"shrimp"},{"quantity":4,"unit":"oz","name":"rice noodles"},{"quantity":1,"unit":"","name":"cucumber"},{"quantity":1,"unit":"","name":"carrot"},{"quantity":1,"unit":"head","name":"lettuce"},{"quantity":1,"unit":"handful","name":"mint"},{"quantity":0.25,"unit":"cup","name":"peanut butter"},{"quantity":2,"unit":"tbsp","name":"hoisin sauce"}]'::jsonb, ARRAY['Cook shrimp and noodles.', 'Cut vegetables into thin strips.', 'Dip each wrapper in warm water.', 'Fill with lettuce, noodles, vegetables, herbs and shrimp and roll up.', 'Whisk peanut butter and hoisin with water for dipping.']::text[], ARRAY['dairy-free', 'gluten-free']::text[], 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1e/Spring_Rolls_%283357696061%29.jpg/960px-Spring_Rolls_%283357696061%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Banh Mi', 'Crusty sandwich with pork and pickled vegetables. (Vietnamese)', 4, 30, '[{"quantity":4,"unit":"","name":"baguette rolls"},{"quantity":1,"unit":"lb","name":"pork tenderloin"},{"quantity":2,"unit":"tbsp","name":"soy sauce"},{"quantity":1,"unit":"tbsp","name":"honey"},{"quantity":1,"unit":"","name":"carrot"},{"quantity":1,"unit":"","name":"cucumber"},{"quantity":0.25,"unit":"cup","name":"rice vinegar"},{"quantity":1,"unit":"tbsp","name":"sugar"},{"quantity":0.25,"unit":"cup","name":"mayonnaise"},{"quantity":1,"unit":"handful","name":"cilantro"},{"quantity":1,"unit":"","name":"jalapeno"}]'::jsonb, ARRAY['Marinate pork in soy sauce and honey, then roast at 400F for 20 minutes.', 'Pickle shredded carrot in vinegar and sugar.', 'Slice pork and cucumber.', 'Spread mayo on rolls and fill with pork, pickles, cucumber, cilantro and jalapeno.']::text[], ARRAY['dairy-free']::text[], 'https://www.themealdb.com/images/media/meals/sonirb1763782831.jpg'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Hummus', 'Smooth chickpea and tahini dip. (Middle Eastern)', 6, 10, '[{"quantity":1,"unit":"can","name":"chickpeas"},{"quantity":0.25,"unit":"cup","name":"tahini"},{"quantity":1,"unit":"","name":"lemon"},{"quantity":1,"unit":"clove","name":"garlic"},{"quantity":3,"unit":"tbsp","name":"olive oil"},{"quantity":0.5,"unit":"tsp","name":"cumin"},{"name":"salt","quantity":0,"unit":""}]'::jsonb, ARRAY['Drain chickpeas, saving the liquid.', 'Blend chickpeas, tahini, lemon juice, garlic and cumin.', 'Add liquid and olive oil until smooth.', 'Season with salt.']::text[], ARRAY['vegan', 'vegetarian', 'gluten-free', 'dairy-free']::text[], 'https://www.themealdb.com/images/media/meals/gpon5u1763801180.jpg'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Falafel', 'Crispy herby chickpea fritters. (Middle Eastern)', 4, 40, '[{"quantity":2,"unit":"cup","name":"dried chickpeas"},{"quantity":1,"unit":"","name":"onion"},{"quantity":3,"unit":"clove","name":"garlic"},{"quantity":1,"unit":"cup","name":"parsley"},{"quantity":1,"unit":"tsp","name":"cumin"},{"quantity":1,"unit":"tsp","name":"coriander"},{"quantity":2,"unit":"tbsp","name":"flour"},{"quantity":1,"unit":"tsp","name":"baking powder"},{"quantity":2,"unit":"cup","name":"vegetable oil"},{"name":"salt","quantity":0,"unit":""}]'::jsonb, ARRAY['Soak chickpeas overnight and drain.', 'Pulse with onion, garlic, parsley and spices.', 'Mix in flour, baking powder and salt.', 'Shape into balls.', 'Fry until deep golden.']::text[], ARRAY['vegan', 'vegetarian', 'dairy-free']::text[], 'https://www.themealdb.com/images/media/meals/u5e9qq1763795441.jpg'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Shakshuka', 'Eggs poached in spiced tomato and pepper sauce. (Middle Eastern)', 4, 30, '[{"quantity":6,"unit":"","name":"eggs"},{"quantity":1,"unit":"can","name":"crushed tomatoes"},{"quantity":1,"unit":"","name":"onion"},{"quantity":1,"unit":"","name":"bell pepper"},{"quantity":3,"unit":"clove","name":"garlic"},{"quantity":1,"unit":"tsp","name":"cumin"},{"quantity":1,"unit":"tsp","name":"paprika"},{"quantity":2,"unit":"tbsp","name":"olive oil"},{"quantity":1,"unit":"handful","name":"parsley"},{"name":"salt","quantity":0,"unit":""}]'::jsonb, ARRAY['Soften onion, pepper and garlic in oil.', 'Add spices and tomatoes and simmer 10 minutes.', 'Make wells and crack in the eggs.', 'Cover and cook until whites are set.', 'Top with parsley.']::text[], ARRAY['vegetarian', 'gluten-free', 'dairy-free']::text[], 'https://www.themealdb.com/images/media/meals/g373701551450225.jpg'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Chicken Shawarma', 'Spiced roast chicken in pita with garlic sauce. (Middle Eastern)', 4, 40, '[{"quantity":1.5,"unit":"lb","name":"chicken thighs"},{"quantity":2,"unit":"tsp","name":"cumin"},{"quantity":2,"unit":"tsp","name":"paprika"},{"quantity":1,"unit":"tsp","name":"turmeric"},{"quantity":1,"unit":"","name":"lemon"},{"quantity":3,"unit":"tbsp","name":"olive oil"},{"quantity":4,"unit":"","name":"pita breads"},{"quantity":1,"unit":"cup","name":"yogurt"},{"quantity":2,"unit":"clove","name":"garlic"},{"quantity":1,"unit":"","name":"tomato"},{"quantity":1,"unit":"","name":"cucumber"}]'::jsonb, ARRAY['Toss chicken with spices, lemon and oil.', 'Roast at 425F for 25 minutes and slice.', 'Mix yogurt with garlic and salt.', 'Fill pitas with chicken, tomato, cucumber and sauce.']::text[], ARRAY[]::text[], 'https://www.themealdb.com/images/media/meals/hcg6l91763596970.jpg'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Tabbouleh', 'Fresh parsley and bulgur salad. (Middle Eastern)', 4, 20, '[{"quantity":0.5,"unit":"cup","name":"bulgur"},{"quantity":2,"unit":"cup","name":"parsley"},{"quantity":0.5,"unit":"cup","name":"mint"},{"quantity":2,"unit":"","name":"tomatoes"},{"quantity":1,"unit":"","name":"cucumber"},{"quantity":3,"unit":"","name":"green onions"},{"quantity":2,"unit":"","name":"lemons"},{"quantity":0.25,"unit":"cup","name":"olive oil"},{"name":"salt","quantity":0,"unit":""}]'::jsonb, ARRAY['Soak bulgur in hot water 15 minutes and drain.', 'Finely chop herbs, tomatoes, cucumber and green onions.', 'Mix with bulgur, lemon juice, olive oil and salt.']::text[], ARRAY['vegan', 'vegetarian', 'dairy-free']::text[], 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/Tabouleh_1.JPG/960px-Tabouleh_1.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Lentil Soup', 'Golden red lentil soup with lemon. (Middle Eastern)', 6, 45, '[{"quantity":1.5,"unit":"cup","name":"red lentils"},{"quantity":1,"unit":"","name":"onion"},{"quantity":1,"unit":"","name":"carrot"},{"quantity":2,"unit":"clove","name":"garlic"},{"quantity":1,"unit":"tsp","name":"cumin"},{"quantity":6,"unit":"cup","name":"vegetable broth"},{"quantity":2,"unit":"tbsp","name":"olive oil"},{"quantity":1,"unit":"","name":"lemon"},{"name":"salt","quantity":0,"unit":""}]'::jsonb, ARRAY['Soften onion, carrot and garlic in oil.', 'Add cumin, lentils and broth.', 'Simmer 25 minutes until lentils break down.', 'Blend until smooth.', 'Finish with lemon juice and salt.']::text[], ARRAY['vegan', 'vegetarian', 'gluten-free', 'dairy-free']::text[], 'https://upload.wikimedia.org/wikipedia/commons/6/61/EgFoodLentilSoup.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Greek Salad', 'Crunchy salad with feta and olives. (Greek)', 4, 15, '[{"quantity":3,"unit":"","name":"tomatoes"},{"quantity":1,"unit":"","name":"cucumber"},{"quantity":1,"unit":"","name":"green bell pepper"},{"quantity":0.5,"unit":"","name":"red onion"},{"quantity":0.5,"unit":"cup","name":"kalamata olives"},{"quantity":6,"unit":"oz","name":"feta cheese"},{"quantity":3,"unit":"tbsp","name":"olive oil"},{"quantity":1,"unit":"tbsp","name":"red wine vinegar"},{"quantity":1,"unit":"tsp","name":"dried oregano"}]'::jsonb, ARRAY['Chop tomatoes, cucumber, pepper and onion.', 'Add olives and top with feta.', 'Drizzle with oil and vinegar and sprinkle with oregano.']::text[], ARRAY['vegetarian', 'gluten-free']::text[], 'https://www.themealdb.com/images/media/meals/k29viq1585565980.jpg'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Chicken Souvlaki', 'Lemon-herb chicken skewers with tzatziki. (Greek)', 4, 40, '[{"quantity":1.5,"unit":"lb","name":"chicken breast"},{"quantity":1,"unit":"","name":"lemon"},{"quantity":3,"unit":"tbsp","name":"olive oil"},{"quantity":2,"unit":"clove","name":"garlic"},{"quantity":1,"unit":"tsp","name":"dried oregano"},{"quantity":1,"unit":"cup","name":"greek yogurt"},{"quantity":0.5,"unit":"","name":"cucumber"},{"name":"salt","quantity":0,"unit":""}]'::jsonb, ARRAY['Cube chicken and marinate in lemon, oil, garlic and oregano.', 'Thread onto skewers.', 'Grill or broil 12 minutes, turning.', 'Grate cucumber into yogurt with salt for tzatziki.']::text[], ARRAY['gluten-free']::text[], 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/%CE%95%CE%BB%CE%BB%CE%B7%CE%BD%CE%B9%CE%BA%CF%8C_%CE%A3%CE%BF%CF%85%CE%B2%CE%BB%CE%AC%CE%BA%CE%B9_-_panoramio.jpg/960px-%CE%95%CE%BB%CE%BB%CE%B7%CE%BD%CE%B9%CE%BA%CF%8C_%CE%A3%CE%BF%CF%85%CE%B2%CE%BB%CE%AC%CE%BA%CE%B9_-_panoramio.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Spanakopita', 'Spinach and feta in flaky pastry. (Greek)', 8, 60, '[{"quantity":1,"unit":"lb","name":"spinach"},{"quantity":8,"unit":"oz","name":"feta cheese"},{"quantity":1,"unit":"","name":"onion"},{"quantity":2,"unit":"","name":"eggs"},{"quantity":1,"unit":"handful","name":"dill"},{"quantity":1,"unit":"lb","name":"phyllo dough"},{"quantity":0.5,"unit":"cup","name":"butter"}]'::jsonb, ARRAY['Cook onion and spinach until wilted and squeeze dry.', 'Mix with feta, eggs and dill.', 'Layer buttered phyllo sheets in a dish.', 'Add filling and top with more buttered sheets.', 'Bake at 375F for 40 minutes.']::text[], ARRAY['vegetarian']::text[], null),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Moussaka', 'Baked eggplant and spiced lamb with bechamel. (Greek)', 8, 100, '[{"quantity":2,"unit":"","name":"eggplants"},{"quantity":1,"unit":"lb","name":"ground lamb"},{"quantity":1,"unit":"","name":"onion"},{"quantity":1,"unit":"can","name":"crushed tomatoes"},{"quantity":1,"unit":"tsp","name":"cinnamon"},{"quantity":3,"unit":"tbsp","name":"butter"},{"quantity":3,"unit":"tbsp","name":"flour"},{"quantity":2,"unit":"cup","name":"milk"},{"quantity":1,"unit":"","name":"egg"},{"quantity":0.5,"unit":"cup","name":"parmesan cheese"},{"quantity":3,"unit":"tbsp","name":"olive oil"}]'::jsonb, ARRAY['Slice and roast the eggplant with oil.', 'Brown lamb with onion, then add tomatoes and cinnamon and simmer.', 'Make a white sauce with butter, flour and milk, then beat in egg and parmesan.', 'Layer eggplant and meat and top with the sauce.', 'Bake at 350F for 45 minutes.']::text[], ARRAY[]::text[], 'https://www.themealdb.com/images/media/meals/ctg8jd1585563097.jpg'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Coq au Vin', 'Chicken braised in red wine with mushrooms. (French)', 6, 90, '[{"quantity":3,"unit":"lb","name":"chicken thighs"},{"quantity":2,"unit":"cup","name":"red wine"},{"quantity":6,"unit":"slice","name":"bacon"},{"quantity":8,"unit":"oz","name":"mushrooms"},{"quantity":1,"unit":"","name":"onion"},{"quantity":2,"unit":"","name":"carrots"},{"quantity":2,"unit":"clove","name":"garlic"},{"quantity":2,"unit":"tbsp","name":"flour"},{"quantity":1,"unit":"cup","name":"chicken broth"},{"quantity":2,"unit":"","name":"sprigs thyme"}]'::jsonb, ARRAY['Fry bacon and brown the chicken in the fat.', 'Cook onion, carrots, garlic and mushrooms.', 'Stir in flour.', 'Add wine, broth, thyme and chicken.', 'Cover and simmer 1 hour.']::text[], ARRAY['dairy-free']::text[], 'https://www.themealdb.com/images/media/meals/qstyvs1505931190.jpg'),
