('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Quiche Lorraine', 'Savoury custard tart with bacon and cheese. (French)', 6, 60, '[{"quantity":1,"unit":"","name":"pie crust"},{"quantity":6,"unit":"slice","name":"bacon"},{"quantity":1,"unit":"cup","name":"gruyere cheese"},{"quantity":4,"unit":"","name":"eggs"},{"quantity":1.5,"unit":"cup","name":"heavy cream"},{"quantity":0.25,"unit":"tsp","name":"nutmeg"},{"name":"salt","quantity":0,"unit":""},{"name":"black pepper","quantity":0,"unit":""}]'::jsonb, ARRAY['Blind-bake the crust for 10 minutes.', 'Fry and crumble the bacon.', 'Whisk eggs, cream, nutmeg, salt and pepper.', 'Scatter bacon and cheese in the crust and pour over the custard.', 'Bake at 350F for 35 minutes.']::text[], ARRAY[]::text[], 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/Quiche.jpg/960px-Quiche.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail'),
('3445b50c-1ea0-4caa-96ea-7951ed5b0262', '0e5b8de4-35ff-4138-8803-32a14f3dab2e', 'Crepes', 'Thin pancakes for sweet or savoury fillings. (French)', 4, 30, '[{"quantity":1,"unit":"cup","name":"flour"},{"quantity":2,"unit":"","name":"eggs"},{"quantity":1.25,"unit":"cup","name":"milk"},{"quantity":2,"unit":"tbsp","name":"butter"},{"quantity":1,"unit":"tbsp","name":"sugar"},{"name":"pinch salt","quantity":0,"unit":""}]'::jsonb, ARRAY['Whisk flour, eggs, milk, sugar, salt and melted butter.', 'Rest the batter 10 minutes.', 'Pour a thin layer into a hot buttered pan.', 'Cook 1 minute per side.']::text[], ARRAY['vegetarian']::text[], null),
